from pager import iter_pages, page_count, slice_page


def test_page_count_basic():
    assert page_count(10, 5) == 2
    assert page_count(11, 5) == 3


def test_slice_basic():
    items = list(range(11))
    assert slice_page(items, 0, 5) == [0, 1, 2, 3, 4]
    assert slice_page(items, 2, 5) == [10]


def test_iter_pages_basic():
    assert iter_pages([1, 2, 3], 2) == [[1, 2], [3]]
